import{_ as t,o as i,c as a,a0 as o}from"./chunks/framework.Bmhw_dvp.js";const g=JSON.parse('{"title":"Listen Together Music","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/music.md","filePath":"en/features/music.md","lastUpdated":null}'),r={name:"en/features/music.md"};function s(l,e,n,d,c,h){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="listen-together-music" tabindex="-1">Listen Together Music <a class="header-anchor" href="#listen-together-music" aria-label="Permalink to &quot;Listen Together Music&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><strong>Listen Together</strong> is the room-based music module of ZViewer. Join a room with friends — the host controls playback and everyone listens in sync. It supports NetEase Cloud Music and Bilibili as dual audio sources, a full-featured lyric player page, and the CLI local proxy for high-quality streaming.</p><p>Core capabilities:</p><ul><li><strong>Dual sources</strong>: NetEase Cloud Music (playlists / daily recommendations / FM / search) + Bilibili (music regions / search / favorites).</li><li><strong>Room sync</strong>: The host switches songs, pauses and seeks; viewers follow in real time with transmission delay compensation.</li><li><strong>Viewer control requests</strong>: Adding songs, switching songs, pause/resume and seeking can all be requested from the host, with one-click auto-approval.</li><li><strong>Lyric player page</strong>: A Hydrogen-style layout — real-time audio spectrum visualization, line-by-line lyrics, translation / Romaji, quality badge, comments and danmaku.</li><li><strong>CLI local proxy</strong>: With ZViewerCLI connected, Bilibili videos are resolved with your own VIP cookie for high-quality backgrounds.</li></ul><hr><h2 id="i-dual-audio-sources" tabindex="-1">I. Dual Audio Sources <a class="header-anchor" href="#i-dual-audio-sources" aria-label="Permalink to &quot;I. Dual Audio Sources&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source</th><th>Content</th></tr></thead><tbody><tr><td><strong>NetEase Cloud Music</strong></td><td>My playlists, daily recommendations, personal FM, search, liked songs, song comments</td></tr><tr><td><strong>Bilibili</strong></td><td>Music region browsing, search, favorites, AI subtitle lyrics, danmaku, comments</td></tr></tbody></table><p>The playlist keeps two independent queues (NetEase / Bilibili) that sync across the room in real time; you can switch between sources freely.</p><h3 id="bilibili-music-region" tabindex="-1">Bilibili Music Region <a class="header-anchor" href="#bilibili-music-region" aria-label="Permalink to &quot;Bilibili Music Region&quot;">​</a></h3><ul><li><strong>Custom tabs</strong>: Top tabs can be added and edited — drag to reorder on desktop, arrow buttons on touch devices; the order persists instantly.</li><li><strong>Region sorting</strong>: The left-hand region list supports the same editing; the selected region and order survive page refreshes.</li><li><strong>Keyword filtering</strong>: Region content can be filtered by blocked words; pagination automatically skips ahead to avoid empty pages.</li></ul><hr><h2 id="ii-playback-control-sync" tabindex="-1">II. Playback Control &amp; Sync <a class="header-anchor" href="#ii-playback-control-sync" aria-label="Permalink to &quot;II. Playback Control &amp; Sync&quot;">​</a></h2><h3 id="host-controls" tabindex="-1">Host controls <a class="header-anchor" href="#host-controls" aria-label="Permalink to &quot;Host controls&quot;">​</a></h3><ul><li>Switch song / pause / resume / seek / play mode (<strong>in order</strong> / repeat one / shuffle / repeat all).</li><li>The default play mode is <strong>in order</strong> (no looping — Bilibili auto-continue only works in this mode).</li></ul><h3 id="viewer-control-requests" tabindex="-1">Viewer control requests <a class="header-anchor" href="#viewer-control-requests" aria-label="Permalink to &quot;Viewer control requests&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Description</th></tr></thead><tbody><tr><td>Add song</td><td>Add a song to the room playlist</td></tr><tr><td>Play song</td><td>Request to play a song from the playlist</td></tr><tr><td>Pause / resume</td><td>Pause or resume playback for everyone</td></tr><tr><td>Seek</td><td>Drag the progress bar to request a position change</td></tr></tbody></table><ul><li>The host sees a drop-in <strong>approval bar</strong> at the top-left corner with Approve / Reject buttons.</li><li>With <strong>auto-approval</strong> enabled, all of the above actions take effect immediately without review.</li><li>After an action succeeds, the viewer sees an &quot;xx synced&quot; receipt at the top-left corner.</li></ul><h3 id="sync-mechanism" tabindex="-1">Sync mechanism <a class="header-anchor" href="#sync-mechanism" aria-label="Permalink to &quot;Sync mechanism&quot;">​</a></h3><ul><li><strong>Delay compensation</strong>: Viewers align playback position based on network latency.</li><li><strong>Instant state sync</strong>: The playlist is fetched immediately on first join (with automatic retry on failure); reconnects re-pull the room state.</li><li><strong>Clearing the playlist stops audio instantly</strong>: The current song stops together with the queue for every member — playback is always room-unified, with no local interludes.</li></ul><hr><h2 id="iii-bilibili-auto-continue" tabindex="-1">III. Bilibili Auto-Continue <a class="header-anchor" href="#iii-bilibili-auto-continue" aria-label="Permalink to &quot;III. Bilibili Auto-Continue&quot;">​</a></h2><p>In &quot;in order&quot; mode, when you press <strong>Next</strong> at the end of the queue, ZViewer automatically fetches 3 related Bilibili videos, appends them to the queue and plays the first one:</p><ul><li><strong>Trigger conditions</strong>: ① Play mode is &quot;in order&quot; (repeat-all wraps back to the queue head instead); ② The current song is a Bilibili item (NetEase playlists don&#39;t support this); ③ &quot;Bilibili auto-continue&quot; is enabled in settings.</li><li>Letting the song finish naturally does NOT append recommendations — the queue simply stops at the end.</li><li>Auto-continue can be toggled off in settings at any time.</li></ul><hr><h2 id="iv-lyric-player-page" tabindex="-1">IV. Lyric Player Page <a class="header-anchor" href="#iv-lyric-player-page" aria-label="Permalink to &quot;IV. Lyric Player Page&quot;">​</a></h2><p>The lyric player page replicates the Hydrogen Music layout:</p><table tabindex="0"><thead><tr><th>Area</th><th>Capabilities</th></tr></thead><tbody><tr><td><strong>Left player card</strong></td><td>Cover corner-bracket animation, real-time audio spectrum, quality badge (actual sample rate / bitrate), UI opacity slider</td></tr><tr><td><strong>Right panel</strong></td><td>Line-by-line lyrics, translation / Romaji, NetEase &amp; Bilibili comment sections (comment-count badge preloaded)</td></tr><tr><td><strong>Background</strong></td><td>Cover blur slider (0–100px); Bilibili items resolve their video as background with a video blur slider and cross-fade on song switch</td></tr><tr><td><strong>Toolbar</strong></td><td>Hover to reveal (always visible on touch); black/white toggle, fullscreen, danmaku toggle, play queue (click to expand / collapse), settings</td></tr></tbody></table><h3 id="ui-opacity-frost-layer-scheme" tabindex="-1">UI opacity (frost-layer scheme) <a class="header-anchor" href="#ui-opacity-frost-layer-scheme" aria-label="Permalink to &quot;UI opacity (frost-layer scheme)&quot;">​</a></h3><p>The &quot;UI opacity&quot; slider uses a <strong>frost layer + UI layer</strong> structure: the bottom layer keeps full-strength frosted-glass blur at all times, while the top layer (tint and text) fades out as a whole — the blur never degrades at any opacity, unlike the old either-or approach.</p><h3 id="bilibili-danmaku" tabindex="-1">Bilibili danmaku <a class="header-anchor" href="#bilibili-danmaku" aria-label="Permalink to &quot;Bilibili danmaku&quot;">​</a></h3><p>Danmaku can be enabled for Bilibili items: layer switching (above / below UI), a danmaku settings panel (style / speed / blocked words / track settings), and persistent danmaku tracks.</p><hr><h2 id="v-cli-local-proxy-mode" tabindex="-1">V. CLI Local Proxy Mode <a class="header-anchor" href="#v-cli-local-proxy-mode" aria-label="Permalink to &quot;V. CLI Local Proxy Mode&quot;">​</a></h2><p>Once <a href="/en/cli/">ZViewerCLI</a> is connected, a CLI panel appears in the lyric page settings:</p><ul><li><strong>High-quality video background</strong>: Bilibili videos are resolved with your local VIP cookie, including VIP-only content.</li><li><strong>Resolution picker</strong>: Auto / 4K / 1080P60 / 1080P+ / 1080P / 720P60 / 720P / 480P / 360P, filtered by your Bilibili VIP status — <strong>non-VIP accounts see up to 1080P</strong>, and a saved VIP tier falls back automatically.</li><li><strong>Progress sync</strong>: The background video stays precisely in sync with the audio; switching songs or resolutions no longer stutters.</li><li><strong>Auto-reconnect</strong>: After a page refresh the CLI reconnects automatically — no need to toggle the setting again.</li></ul><hr><h2 id="vi-favorites-search" tabindex="-1">VI. Favorites &amp; Search <a class="header-anchor" href="#vi-favorites-search" aria-label="Permalink to &quot;VI. Favorites &amp; Search&quot;">​</a></h2><ul><li><strong>Bilibili heart</strong>: One-click favorite to a chosen folder from the lyric page or the play bar; click again to un-favorite. The collected state is restored across sessions via Bilibili&#39;s official aggregated query (lit if the video is in any folder).</li><li><strong>Folder picker</strong>: Add a Bilibili video to any of your favorite folders.</li><li><strong>Search on NetEase</strong>: Extract the song title from a playing Bilibili video and search NetEase Cloud Music in one click — with local preview and one-click &quot;like&quot; to your liked-songs list (already-liked songs show a red heart).</li></ul><hr><h2 id="vii-mobile" tabindex="-1">VII. Mobile <a class="header-anchor" href="#vii-mobile" aria-label="Permalink to &quot;VII. Mobile&quot;">​</a></h2><ul><li><strong>Fully responsive</strong>: Player card / lyric panel adapt to the screen, the toolbar reflows in portrait, and popups degrade into bottom sheets.</li><li><strong>Touch friendly</strong>: Controls stay visible without hover; sliders don&#39;t scroll the page while dragging.</li><li><strong>Voice optimization</strong>: Mobile voice chat uses Opus 40ms frames + inband FEC for smoother audio on weak networks.</li></ul><hr><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><h3 id="why-doesn-t-auto-continue-trigger" tabindex="-1">Why doesn&#39;t auto-continue trigger? <a class="header-anchor" href="#why-doesn-t-auto-continue-trigger" aria-label="Permalink to &quot;Why doesn&#39;t auto-continue trigger?&quot;">​</a></h3><p>Three conditions must all hold: ① Play mode is &quot;in order&quot;; ② The current song is a Bilibili item; ③ &quot;Bilibili auto-continue&quot; is enabled in settings.</p><h3 id="why-can-t-i-see-4k-1080p60-in-the-cli-resolution-picker" tabindex="-1">Why can&#39;t I see 4K / 1080P60 in the CLI resolution picker? <a class="header-anchor" href="#why-can-t-i-see-4k-1080p60-in-the-cli-resolution-picker" aria-label="Permalink to &quot;Why can&#39;t I see 4K / 1080P60 in the CLI resolution picker?&quot;">​</a></h3><p>Resolution tiers are filtered by your Bilibili VIP status; non-VIP accounts see up to 1080P. Make sure the CLI uses a VIP account&#39;s cookie, then reopen the settings panel to refresh the tiers.</p><h3 id="can-viewers-seek" tabindex="-1">Can viewers seek? <a class="header-anchor" href="#can-viewers-seek" aria-label="Permalink to &quot;Can viewers seek?&quot;">​</a></h3><p>Yes. Dragging the progress bar sends a request to the host: with auto-approval it takes effect immediately; otherwise the host must click Approve on the top-left bar.</p><h3 id="does-the-song-keep-playing-after-the-playlist-is-cleared" tabindex="-1">Does the song keep playing after the playlist is cleared? <a class="header-anchor" href="#does-the-song-keep-playing-after-the-playlist-is-cleared" aria-label="Permalink to &quot;Does the song keep playing after the playlist is cleared?&quot;">​</a></h3><p>No. Clearing the playlist stops the current song instantly for every member — playback is always controlled by the room.</p>',52)])])}const p=t(r,[["render",s]]);export{g as __pageData,p as default};
